import math

def t_pdf(x, df):
    c = math.exp(math.lgamma((df+1)/2) - math.lgamma(df/2) - 0.5*math.log(df*math.pi))
    return c * (1 + x*x/df) ** (-(df+1)/2)

def simpson(f, a, b, n):
    if n % 2:
        n += 1
    h = (b-a)/n
    s = f(a) + f(b)
    for i in range(1, n):
        s += (4 if i%2 else 2) * f(a+i*h)
    return s*h/3

def t_cdf(x, df):
    return simpson(lambda u: t_pdf(u, df), -50, x, 20000)

def f_pdf(x, d1, d2):
    c = math.exp(math.lgamma((d1+d2)/2) - math.lgamma(d1/2) - math.lgamma(d2/2))
    c *= (d1/d2)**(d1/2)
    return c * x**(d1/2-1) * (1 + (d1/d2)*x)**(-(d1+d2)/2)

def f_cdf(x, d1, d2):
    return simpson(lambda u: f_pdf(u, d1, d2), 0, x, 10000)

def f_quantile(p, d1, d2):
    lo, hi = 0.0, 20.0
    for _ in range(60):
        mid = (lo+hi)/2
        if f_cdf(mid, d1, d2) < p:
            lo = mid
        else:
            hi = mid
    return (lo+hi)/2

print(f'{t_cdf(1.812, 10):.2f}')
print(f'{f_quantile(0.95, 5, 10):.2f}')
